solution.exercise.cpp:
#include "exercise.h"
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
void graph_free(graph*g){free(g->nodes);free(g->edges);free(g->attributes);memset(g,0,sizeof *g);}const char*graph_create(graph*g,const graph_item*x,size_t n){memset(g,0,sizeof *g);if(n&&!x)return "Graph data malformed";for(size_t i=0;i<n;i++){const graph_item*p=x+i;const char*error=NULL;if(p->arity<3)error="Graph item incomplete";else if(p->kind==0&&p->arity!=3)error="Node is malformed";else if(p->kind==1&&p->arity!=4)error="Edge is malformed";else if(p->kind==2&&p->arity!=3)error="Attribute is malformed";else if(p->kind<0||p->kind>2)error="Unknown item";if(error){graph_free(g);return error;}if(p->kind==0){g->nodes=(graph_item*)realloc(g->nodes,(g->node_count+1)*sizeof(graph_item));g->nodes[g->node_count++]=*p;}else if(p->kind==1){g->edges=(graph_item*)realloc(g->edges,(g->edge_count+1)*sizeof(graph_item));g->edges[g->edge_count++]=*p;}else{size_t k=0;while(k<g->attribute_count&&strcmp(g->attributes[k].key,p->name))k++;if(k==g->attribute_count){g->attributes=(attribute*)realloc(g->attributes,(++g->attribute_count)*sizeof(attribute));}g->attributes[k].key=p->name;g->attributes[k].value=p->destination;}}return NULL;}

