#include "exercise.h"
#include <assert.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdio.h>
static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
graph_item x[]={{0,3,"a",NULL,NULL,0},{1,4,"a","b",NULL,0},{2,3,"color","red",NULL,0},{2,3,"color","blue",NULL,0}};graph g;assert(!graph_create(&g,x,4));assert(g.node_count==1&&g.edge_count==1&&g.attribute_count==1&&!strcmp(g.attributes[0].value,"blue"));graph_free(&g);graph_item bad={0,4,"a",NULL,NULL,0};assert(!strcmp(graph_create(&g,&bad,1),"Node is malformed"));bad.kind=99;bad.arity=3;assert(!strcmp(graph_create(&g,&bad,1),"Unknown item"));bad.arity=1;assert(!strcmp(graph_create(&g,&bad,1),"Graph item incomplete"));

return 0;}
